#include <string.h>

void process_string_info(char *dest, size_t dest_capacity, const char *src, size_t src_length) {
    if (dest == NULL || src == NULL || dest_capacity == 0) {
        return;
    }

    size_t copy_length = src_length;
    if (copy_length > dest_capacity - 1) {
        copy_length = dest_capacity - 1;
    }

    memcpy(dest, src, copy_length);
    dest[copy_length] = '\0';
}
